// Some portions generated by Codex
package org.eclipse.rdf4j.sail.lmdb;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertNotEquals;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.io.File;
import java.nio.file.Path;
import java.util.HashSet;
import java.util.Set;

import org.eclipse.rdf4j.common.iteration.CloseableIteration;
import org.eclipse.rdf4j.common.transaction.IsolationLevels;
import org.eclipse.rdf4j.model.IRI;
import org.eclipse.rdf4j.model.Statement;
import org.eclipse.rdf4j.model.TripleTerm;
import org.eclipse.rdf4j.model.ValueFactory;
import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.sail.SailConnection;
import org.eclipse.rdf4j.sail.lmdb.config.LmdbStoreConfig;
import org.eclipse.rdf4j.sail.lmdb.model.LmdbValue;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.Timeout;
import org.junit.jupiter.api.io.TempDir;

class LmdbMaintenanceGrowthTest {

	private static final ValueFactory VF = SimpleValueFactory.getInstance();
	private static final IRI PREDICATE = VF.createIRI("urn:lmdb:maintenance-growth:predicate");
	private static final long VALUE_MAP_BYTES = 2L * 1024L * 1024L;
	private static final long TARGET_HIGH_WATER_BYTES = 1536L * 1024L;
	private static final int RETIRED_ORPHAN_COUNT = 4096;

	@Test
	@Timeout(value = 60, unit = java.util.concurrent.TimeUnit.SECONDS)
	void startupRetirementRecoveryGrowsFromItsNaturalCommittedFootprint(@TempDir Path dataDirectory)
			throws Exception {
		LmdbStoreConfig fixedCapacity = config(false);
		IRI subject = VF.createIRI("urn:lmdb:maintenance-growth:live-subject");
		TripleTerm quoted = VF.createTripleTerm(subject, PREDICATE, VF.createLiteral("nested committed value"));
		TripleTerm nestedQuoted = VF.createTripleTerm(subject, PREDICATE, quoted);
		IRI orphan = VF.createIRI("urn:lmdb:maintenance-growth:orphan");
		LmdbStore initial = new LmdbStore(dataDirectory.toFile(), fixedCapacity);
		initial.init();
		try (SailConnection connection = initial.getConnection()) {
			connection.begin(IsolationLevels.SNAPSHOT);
			connection.addStatement(subject, PREDICATE, nestedQuoted);
			connection.commit();
		} finally {
			initial.shutDown();
		}

		StoreProperties properties = new StoreProperties(dataDirectory.toFile());
		properties.load();
		ValueStore valueStore = new ValueStore(new File(dataDirectory.toFile(), "values"), properties, fixedCapacity);
		try {
			Set<Long> retiredIds = new HashSet<>();
			valueStore.startTransaction(true);
			long liveQuotedId = valueStore.getId(quoted);
			assertNotEquals(LmdbValue.UNKNOWN_ID, liveQuotedId, "the nested live value must exist before retirement");
			retiredIds.add(liveQuotedId);
			for (int i = 0; i < RETIRED_ORPHAN_COUNT; i++) {
				IRI retired = VF.createIRI("urn:lmdb:maintenance-growth:retired:", "orphan-" + i);
				long id = valueStore.getId(retired, true);
				assertNotEquals(LmdbValue.UNKNOWN_ID, id, "each unreferenced retirement candidate must be real");
				retiredIds.add(id);
			}
			long orphanId = valueStore.getId(orphan, true);
			assertNotEquals(LmdbValue.UNKNOWN_ID, orphanId);
			retiredIds.add(orphanId);
			valueStore.recordRetiredIds(retiredIds, 0L);
			valueStore.commit();
			assertTrue(valueStore.hasRetiredIds(), "the retirement intent must be durable before startup recovery");

			int fillerBatch = 0;
			while (valueStore.committedHighWaterBytes() < TARGET_HIGH_WATER_BYTES) {
				valueStore.startTransaction(true);
				for (int i = 0; i < 512; i++) {
					valueStore.getId(VF.createLiteral("committed-padding-" + fillerBatch + "-" + i
							+ "-" + "x".repeat(72)), true);
				}
				valueStore.commit();
				fillerBatch++;
				assertTrue(fillerBatch < 64, "the natural ValueStore fill must remain bounded");
			}
			assertTrue(valueStore.committedHighWaterBytes() >= TARGET_HIGH_WATER_BYTES,
					"committed dictionary data must approach the fixed map's hard capacity");
			assertTrue(valueStore.committedHighWaterBytes() < VALUE_MAP_BYTES,
					"the map must still be usable before auto-growing recovery is enabled");
		} finally {
			valueStore.close();
		}

		LmdbStore reopened = new LmdbStore(dataDirectory.toFile(), config(true));
		reopened.init();
		try (SailConnection connection = reopened.getConnection();
				CloseableIteration<? extends Statement> statements = connection.getStatements(null, PREDICATE, null,
						false)) {
			assertTrue(statements.hasNext(), "the live committed quoted statement must survive startup GC");
			Statement statement = statements.next();
			assertEquals(subject, statement.getSubject());
			assertEquals(nestedQuoted, statement.getObject(),
					"liveness revalidation must preserve the live recursive quoted value");
			assertTrue(statement.getObject().isTripleTerm());
			assertEquals(quoted, ((TripleTerm) statement.getObject()).getObject());
			assertFalse(statements.hasNext());
			assertFalse(reopened.getBackingStore().hasRetiredValueIds(),
					"startup recovery must consume the durable retirement intent");
		} finally {
			reopened.shutDown();
		}

		StoreProperties reopenedProperties = new StoreProperties(dataDirectory.toFile());
		reopenedProperties.load();
		ValueStore recoveredValues = new ValueStore(new File(dataDirectory.toFile(), "values"), reopenedProperties,
				config(true));
		try {
			assertEquals(LmdbValue.UNKNOWN_ID, recoveredValues.getId(orphan),
					"the startup liveness pass must reclaim the unreferenced retired value");
		} finally {
			recoveredValues.close();
		}
	}

	private static LmdbStoreConfig config(boolean autoGrow) {
		return new LmdbStoreConfig("spoc,posc")
				.setForceSync(true)
				.setTripleDBSize(8L * 1024L * 1024L)
				.setValueDBSize(VALUE_MAP_BYTES)
				.setAutoGrow(autoGrow);
	}
}
